aurora-veil.css:
.fx-aurora-veil {
  position: relative;
  align-self: stretch;
  flex: 1 1 auto;
  width: 100%;
  min-height: 9rem;
  overflow: hidden;
  border-radius: 0.75rem;
  /* Shown until the shader's first frame, and permanently if WebGL is
     unavailable. Derived from the program's palette, not typed twice. */
  background: linear-gradient(145deg, #f4f6ff 0%, #0d9488 58%, #4f46e5 100%);
}

.fx-aurora-veil > canvas {
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
}

.dark .fx-aurora-veil {
  background: linear-gradient(145deg, #05060f 0%, #34d399 58%, #6366f1 100%);
}

